    "assistant.searching": "স্কিম ক্যাটালগ পরীক্ষা করা হচ্ছে...",
    "assistant.welcome": "নমস্তে ! আমি আপনাকে বর্তমান স্কিম ক্যাটালগ থেকে তথ্য খুঁজতে সাহায্য করতে পারি। আমি ব্যক্তিগত যোগ্যতা নিশ্চিত করতে বা আবেদন জমা দিতে পারি না।",
