    "safetyCentre.i4cLinkLabel": "একটি নতুন ট্যাবে ইন্ডিয়ান সাইবার ক্রাইম কোঅর্ডিনেশন সেন্টারের ওয়েবসাইট খুলুন",
    "safetyCentre.consumerName": "জাতীয় ভোক্তা হেল্পলাইন",
    "safetyCentre.q2Option2": "ব্যক্তিটি বিশ্বস্ত মনে হলেই শেয়ার করুন।",
    "safetyCentre.q2Option3": "OTP প্রকাশ করবেন না; স্বাধীনভাবে প্রাসঙ্গিক অফিসিয়াল পরিষেবার সাথে যোগাযোগ করুন।",
    "safetyCentre.q2Option4": "পরিবর্তে আপনার পাসওয়ার্ড পাঠান.",
    "safetyCentre.q2Explanation": "কলকারীদের কাছে ওটিপি বা পাসওয়ার্ড প্রকাশ করবেন না। আপনি স্বাধীনভাবে খুঁজে পাওয়া যোগাযোগের বিবরণ ব্যবহার করে অফিসিয়াল পরিষেবার সাথে যোগাযোগ করুন।",
    "safetyCentre.q3Option1": "অবিলম্বে আপনার আধার এবং ব্যাঙ্কের বিবরণ লিখুন।",
    "safetyCentre.q3Option2": "অন্য আবেদনকারীদের লিঙ্ক ফরোয়ার্ড.",
    "safetyCentre.q3Option3": "একটি অনুমোদিত সরকারী উৎসের মাধ্যমে আবেদনের লিঙ্কটি যাচাই করুন।",
    "safetyCentre.q3Option4": "ওয়েবসাইটটিকে বিশ্বাস করুন কারণ এতে একটি সরকারী লোগো রয়েছে।",
    "safetyCentre.q3Explanation": "একটি লোগো প্রমাণ করে না যে একটি ওয়েবসাইট আসল। বিস্তারিত শেয়ার করার আগে একটি অনুমোদিত সরকারি ওয়েবসাইটের মাধ্যমে আবেদনের লিঙ্কটি খুঁজুন।",
    "safetyCentre.q4Option1": "অর্থ প্রদান করুন কারণ অফারটি আকর্ষণীয় শোনাচ্ছে।",
    "safetyCentre.q4Option2": "দাবিটি সাবধানতার সাথে বিবেচনা করুন এবং একটি অফিসিয়াল উত্সের মাধ্যমে স্কিমের যোগ্যতার নিয়মগুলি যাচাই করুন৷",
