    "safetyCentre.q5Explanation": "শুধুমাত্র যাচাইকৃত অ্যাপ্লিকেশন চ্যানেলের মাধ্যমে প্রয়োজনীয় নথি শেয়ার করুন। কোনো মধ্যস্থতাকারীর কাছে পাসওয়ার্ড, পিন বা ওটিপি প্রকাশ করবেন না।",
