    "safetyCentre.i4cDescription": "भारताच्या सायबर क्राईम प्रतिसादासाठी समन्वय, क्षमता निर्माण आणि संसाधनांना समर्थन देणारे गृह मंत्रालय केंद्र.",
    "safetyCentre.i4cButton": "I4C वेबसाइटला भेट द्या",
    "safetyCentre.i4cLinkLabel": "भारतीय सायबर गुन्हे समन्वय केंद्राची वेबसाइट नवीन टॅबमध्ये उघडा",
    "safetyCentre.consumerName": "राष्ट्रीय ग्राहक हेल्पलाइन",
    "safetyCentre.consumerDescription": "ग्राहक व्यवहार विभागामार्फत ग्राहकांच्या तक्रारी आणि तक्रारींसाठी मदत मिळवा.",
    "safetyCentre.consumerButton": "ग्राहक हेल्पलाइनला भेट द्या",
    "safetyCentre.consumerLinkLabel": "नवीन टॅबमध्ये राष्ट्रीय ग्राहक हेल्पलाइन वेबसाइट उघडा",
    "safetyCentre.consumer1915Description": "ग्राहक तक्रार सहाय्यासाठी 1915 वर कॉल करा. ही सायबर आर्थिक फसवणूक हेल्पलाइन नाही.",
    "safetyCentre.call1915Label": "राष्ट्रीय ग्राहक हेल्पलाइन सहाय्यासाठी 1915 वर कॉल करा",
    "safetyCentre.question1": "एखाद्या व्यक्तीचा दावा आहे की तुम्ही त्यांच्या वैयक्तिक UPI खात्यात प्रक्रिया शुल्क भरल्यास तुम्हाला निश्चितपणे सरकारी योजनेचा लाभ मिळेल. आपण काय करावे?",
    "safetyCentre.question2": "सरकारी अधिकारी असल्याचा दावा करणारे कोणीतरी तुमचा योजनेचा अर्ज मंजूर करण्यासाठी तुम्हाला फोनवर ओटीपी प्रकट करण्यास सांगते. आपण काय करावे?",
    "safetyCentre.question3": "तुम्ही ओळखत नसलेल्या स्कीम ॲप्लिकेशन वेबसाइटच्या लिंकसह तुम्हाला एक मेसेज प्राप्त होतो. आपण काय करावे?",
    "safetyCentre.question4": "एका सोशल मीडिया पोस्टमध्ये असा दावा करण्यात आला आहे की, जो कोणी अल्प शुल्क भरतो त्यांना कोणत्याही पात्रता तपासणीशिवाय सरकारी लाभ मिळेल. सर्वात सुरक्षित प्रतिसाद काय आहे?",
    "safetyCentre.question5": "तुमच्या योजनेच्या अर्जावर जलद प्रक्रिया करण्यासाठी एक अज्ञात व्यक्ती ओळख दस्तऐवज, बँक तपशील आणि पासवर्ड विचारते. आपण काय करावे?",
    "safetyCentre.question6": "जर तुम्ही अज्ञात खात्यात तातडीने पैसे हस्तांतरित केले नाही तर तुमचा विद्यमान योजनेचा लाभ रद्द केला जाईल असे संदेशात म्हटले आहे. आपण काय करावे?",
    "safetyCentre.q1Option1": "लाभ सुरक्षित करण्यासाठी त्वरित पैसे द्या.",
    "safetyCentre.q1Option2": "योजनेचे अधिकृत नियम तपासा आणि पैसे देण्यापूर्वी विनंतीची पडताळणी करा.",
    "safetyCentre.q1Option3": "तुमचे बँक तपशील त्या व्यक्तीसोबत शेअर करा.",
    "safetyCentre.q1Option4": "ऑफर मित्रांना फॉरवर्ड करा.",
    "safetyCentre.q1Explanation": "वैयक्तिक UPI पेमेंट आणि हमी लाभ हे चेतावणी चिन्हे आहेत. अधिकृत योजना सूचना तपासा आणि कोणतेही शुल्क भरण्यापूर्वी स्वतंत्रपणे सत्यापित करा.",
    "safetyCentre.q2Option1": "त्या व्यक्तीला तुमचे नाव माहीत असल्यास OTP शेअर करा.",
    "safetyCentre.q4Explanation": "वैध लाभांमध्ये योजनेचे नियम आणि पात्रता निकष असतात. हमखास निवडीची पसंती आणि आश्वासने पुरावा नाहीत.",
    "safetyCentre.q5Option1": "सर्व काही त्वरित पाठवा.",
    "safetyCentre.q5Option2": "फक्त तुमचे पासवर्ड शेअर करा.",
    "safetyCentre.q5Option3": "व्यक्तीचे अधिकार सत्यापित करा आणि अधिकृत अनुप्रयोग चॅनेल वापरा; पासवर्ड किंवा OTP कधीही उघड करू नका.",
    "safetyCentre.q5Option4": "व्यक्तीला त्यांच्या ओळखीची पुष्टी करण्यासाठी पैसे द्या.",
    "safetyCentre.q5Explanation": "आवश्यक कागदपत्रे केवळ सत्यापित अनुप्रयोग चॅनेलद्वारे सामायिक करा. पासवर्ड, पिन किंवा ओटीपी मध्यस्थाकडे कधीही उघड करू नका.",
    "safetyCentre.q6Option1": "लगेच पैसे ट्रान्सफर करा.",
    "safetyCentre.q6Option2": "तुमच्या बँकिंग क्रेडेंशियलसह उत्तर द्या.",
    "safetyCentre.q6Option3": "कारवाई करण्यापूर्वी संबंधित अधिकृत सेवेद्वारे दावा स्वतंत्रपणे सत्यापित करा.",
    "safetyCentre.q6Option4": "संदेशातील प्रत्येक लिंकवर क्लिक करा.",
    "safetyCentre.q6Explanation": "तत्परता आणि धमक्या हे सामान्य दबाव डावपेच आहेत. कार्य करण्यापूर्वी योजनेच्या अधिकृत सेवेशी स्वतंत्रपणे संपर्क साधा.",
