    "safetyCentre.q3Explanation": "लोगो वेबसाइट अस्सल असल्याचे सिद्ध करत नाही. तपशील शेअर करण्यापूर्वी अधिकृत सरकारी वेबसाइटद्वारे अर्जाची लिंक शोधा.",
