    "dashboard.ruleEngineDesc": "திட்ட அட்டவணை மற்றும் உங்கள் சுயவிவரத் தகவலின் அடிப்படையில் பரிந்துரைகள் உள்ளன. அதிகாரப்பூர்வ திட்ட ஆதாரத்துடன் விவரங்களை உறுதிப்படுத்தவும்.",
