    "safetyCentre.heroSubtitle": "மோசடியான திட்டச் சலுகைகளை அங்கீகரிக்கவும், உங்கள் தனிப்பட்ட தகவலைப் பாதுகாக்கவும், நம்பகமான ஆதாரங்கள் மூலம் பாதுகாப்பாக விண்ணப்பிக்கவும் கற்றுக்கொள்ளுங்கள்.",
    "safetyCentre.takeQuiz": "பாதுகாப்பு வினாடி வினா எடுக்கவும்",
    "safetyCentre.quizTitle": "மோசடி விழிப்புணர்வு வினாடிவினா",
    "safetyCentre.quizDescription": "ஒவ்வொரு சூழ்நிலையிலும் பாதுகாப்பான பதிலைத் தேர்ந்தெடுக்கவும். நீங்கள் செல்லும்போது கற்றுக்கொள்ளுங்கள்.",
    "safetyCentre.quizProgressLabel": "வினாடி வினா முன்னேற்றம்",
