    "safetyCentre.incorrectFeedback": "அது பாதுகாப்பான தேர்வு அல்ல.",
    "safetyCentre.correctAnswer": "சரியான பதில்",
    "safetyCentre.explanationLabel": "இது ஏன் பாதுகாப்பானது",
    "safetyCentre.previous": "முந்தைய",
