    "safetyCentre.showResults": "உங்கள் மதிப்பெண்ணைப் பாருங்கள்",
    "safetyCentre.answerAll": "உங்கள் மதிப்பெண்ணைக் காண ஆறு கேள்விகளுக்கும் பதிலளிக்கவும்.",
    "safetyCentre.quizComplete": "வினாடி வினா முடிந்தது",
    "safetyCentre.scoreLine": "உங்கள் மதிப்பெண்: {total} இல் {score}",
    "safetyCentre.resultExcellent": "சிறந்த வேலை — பொதுவான திட்ட மோசடிகளை எவ்வாறு கண்டறிவது என்பது உங்களுக்குத் தெரியும்.",
    "safetyCentre.resultGood": "நல்ல முயற்சி. உங்கள் பாதுகாப்பு பழக்கங்களை வலுப்படுத்த, தவறவிட்ட பதில்களை மதிப்பாய்வு செய்யவும்.",
    "safetyCentre.resultReview": "இன்னும் கொஞ்சம் பயிற்சி செய்வது சந்தேகத்திற்குரிய சலுகைகளை அடையாளம் காண உதவும். கீழே உள்ள வழிகாட்டுதலை மதிப்பாய்வு செய்யவும்.",
    "safetyCentre.retry": "வினாடி வினாவை மீண்டும் முயற்சிக்கவும்",
    "safetyCentre.stepTitle": "விண்ணப்பிக்கும் முன் எப்படி பாதுகாப்பாக இருக்க வேண்டும்",
    "safetyCentre.step1Title": "திட்டத்தை சரிபார்க்கவும்",
    "safetyCentre.step1Body": "இந்தத் திட்டம் உள்ளதா, யார் தகுதியானவர்கள், எந்தெந்த ஆவணங்கள் தேவை, அதற்கான அதிகாரப்பூர்வ அரசாங்க ஆதாரம் மூலம் எவ்வாறு விண்ணப்பிப்பது என்பதைச் சரிபார்க்கவும்.",
    "safetyCentre.step2Title": "பயன்பாட்டு இணைப்பைச் சரிபார்க்கவும்",
    "safetyCentre.step2Body": "நம்பகமான அரசாங்க மூலத்திலிருந்து விண்ணப்பத்தைப் பெறவும். அனுப்பப்பட்ட இணைப்புகள், சுருக்கப்பட்ட URLகள் அல்லது அரசாங்க லோகோவை மட்டும் நம்ப வேண்டாம்.",
    "safetyCentre.step3Title": "பணம் செலுத்துவதில் கவனமாக இருங்கள்",
    "safetyCentre.step3Body": "எந்தவொரு கட்டணத்திற்கும் திட்டத்தின் அதிகாரப்பூர்வ வழிமுறைகளைப் பார்க்கவும். உத்தரவாதமான ஒப்புதலுக்கு ஈடாக தனிப்பட்ட வங்கி அல்லது UPI கட்டணக் கோரிக்கைகள் குறித்து எச்சரிக்கையாக இருங்கள்.",
    "safetyCentre.step4Title": "தனிப்பட்ட தகவல்களைப் பாதுகாக்கவும்",
    "safetyCentre.step4Body": "கடவுச்சொற்கள், பின்கள் அல்லது OTPகளை இடைத்தரகர்களுடன் ஒருபோதும் பகிர வேண்டாம். சரிபார்க்கப்பட்ட விண்ணப்ப சேனல் மூலம் மட்டுமே தேவையான ஆவணங்களை சமர்ப்பிக்கவும்.",
    "safetyCentre.step5Title": "எதிர்பாராத செய்திகளைச் சரிபார்க்கவும்",
    "safetyCentre.step5Body": "பதிலளிப்பதற்கு முன், இணைப்புகளைத் திறப்பதற்கு, பணம் அனுப்புவதற்கு அல்லது தகவல்களைப் பகிர்வதற்கு முன் சந்தேகத்திற்குரிய அழைப்புகள், குறுஞ்செய்திகள், மின்னஞ்சல்கள் மற்றும் சமூக இடுகைகளை சுயாதீனமாகச் சரிபார்க்கவும்.",
    "safetyCentre.resourcesTitle": "அவசர உதவி மற்றும் அதிகாரப்பூர்வ ஆதாரங்கள்",
