    "assistant.searching": "திட்ட அட்டவணையைச் சரிபார்க்கிறது...",
    "assistant.welcome": "நமஸ்தே! தற்போதைய திட்ட அட்டவணையில் இருந்து தகவலைப் பார்க்க நான் உங்களுக்கு உதவ முடியும். என்னால் தனிப்பட்ட தகுதியை உறுதிப்படுத்தவோ விண்ணப்பங்களைச் சமர்ப்பிக்கவோ முடியாது.",
