    "safetyCentre.heroTitle": "திட்ட மோசடி விழிப்புணர்வு மையம்",
    "safetyCentre.resourcesDescription": "உங்கள் அக்கறையுடன் பொருந்தக்கூடிய அதிகாரப்பூர்வ சேவையைப் பயன்படுத்தவும். இந்த சேவைகள் இழந்த பணத்தை மீட்டெடுப்பதற்கு உத்தரவாதம் அளிக்காது.",
