    "auth.resetOtpSent": "உங்கள் மொபைல் எண்ணுக்கு OTP அனுப்பப்பட்டது.",
    "auth.otpVerified": "OTP சரிபார்க்கப்பட்டது. கீழே ஒரு புதிய கடவுச்சொல்லை அமைக்கவும்.",
    "auth.resetFailed": "கடவுச்சொல்லை மீட்டமைக்க முடியவில்லை.",
