    "safetyCentre.heroTitle": "స్కీమ్ స్కామ్ అవేర్‌నెస్ సెంటర్",
    "safetyCentre.step1Body": "పథకం ఉనికిలో ఉందా, ఎవరు అర్హులు, ఏ పత్రాలు అవసరం మరియు తగిన అధికారిక ప్రభుత్వ మూలం ద్వారా ఎలా దరఖాస్తు చేయాలో తనిఖీ చేయండి.",
    "safetyCentre.step2Title": "అప్లికేషన్ లింక్‌ని ధృవీకరించండి",
    "safetyCentre.step2Body": "విశ్వసనీయ ప్రభుత్వ మూలం నుండి అప్లికేషన్‌ను చేరుకోండి. ఫార్వార్డ్ చేసిన లింక్‌లు, సంక్షిప్త URLలు లేదా ప్రభుత్వ లోగోపై మాత్రమే ఆధారపడవద్దు.",
    "safetyCentre.step3Title": "చెల్లింపుల విషయంలో జాగ్రత్తగా ఉండండి",
    "safetyCentre.step3Body": "ఏదైనా రుసుము కోసం పథకం యొక్క అధికారిక సూచనలను తనిఖీ చేయండి. గ్యారెంటీ ఆమోదానికి బదులుగా వ్యక్తిగత బ్యాంక్ లేదా UPI చెల్లింపు డిమాండ్ల పట్ల జాగ్రత్తగా ఉండండి.",
    "safetyCentre.step4Title": "వ్యక్తిగత సమాచారాన్ని రక్షించండి",
    "safetyCentre.step4Body": "పాస్‌వర్డ్‌లు, పిన్‌లు లేదా OTPలను మధ్యవర్తితో ఎప్పుడూ షేర్ చేయవద్దు. ధృవీకరించబడిన అప్లికేషన్ ఛానెల్ ద్వారా మాత్రమే అవసరమైన పత్రాలను సమర్పించండి.",
    "safetyCentre.step5Title": "ఊహించని సందేశాలను ధృవీకరించండి",
    "safetyCentre.step5Body": "ప్రత్యుత్తరం ఇవ్వడానికి, లింక్‌లను తెరవడానికి, డబ్బు పంపడానికి లేదా సమాచారాన్ని పంచుకోవడానికి ముందు అనుమానాస్పద కాల్‌లు, టెక్స్ట్‌లు, ఇమెయిల్‌లు మరియు సామాజిక పోస్ట్‌లను స్వతంత్రంగా తనిఖీ చేయండి.",
    "safetyCentre.resourcesTitle": "అత్యవసర సహాయం మరియు అధికారిక వనరులు",
    "safetyCentre.heroSubtitle": "మోసపూరిత స్కీమ్ ఆఫర్‌లను గుర్తించడం, మీ వ్యక్తిగత సమాచారాన్ని రక్షించడం మరియు విశ్వసనీయ మూలాల ద్వారా సురక్షితంగా దరఖాస్తు చేసుకోవడం నేర్చుకోండి.",
