    "safetyCentre.q1Option3": "మీ బ్యాంక్ వివరాలను వ్యక్తితో పంచుకోండి.",
    "safetyCentre.q1Option4": "ఆఫర్‌ను స్నేహితులకు ఫార్వార్డ్ చేయండి.",
    "safetyCentre.q1Explanation": "వ్యక్తిగత UPI చెల్లింపు మరియు హామీ ప్రయోజనం హెచ్చరిక సంకేతాలు. అధికారిక పథకం సూచనలను తనిఖీ చేయండి మరియు చెల్లించే ముందు ఏదైనా రుసుమును స్వతంత్రంగా ధృవీకరించండి.",
    "safetyCentre.q2Option1": "వ్యక్తికి మీ పేరు తెలిస్తే OTPని షేర్ చేయండి.",
    "safetyCentre.consumerDescription": "వినియోగదారుల వ్యవహారాల శాఖ ద్వారా వినియోగదారుల ఫిర్యాదులు మరియు ఫిర్యాదులతో సహాయం పొందండి.",
    "safetyCentre.consumerButton": "వినియోగదారుల హెల్ప్‌లైన్‌ని సందర్శించండి",
    "safetyCentre.consumerLinkLabel": "నేషనల్ కన్స్యూమర్ హెల్ప్‌లైన్ వెబ్‌సైట్‌ను కొత్త ట్యాబ్‌లో తెరవండి",
    "safetyCentre.consumer1915Description": "వినియోగదారుల ఫిర్యాదు సహాయం కోసం 1915కు కాల్ చేయండి. ఇది సైబర్ ఆర్థిక మోసం హెల్ప్‌లైన్ కాదు.",
    "safetyCentre.call1915Label": "నేషనల్ కన్స్యూమర్ హెల్ప్‌లైన్ సహాయం కోసం 1915కు కాల్ చేయండి",
    "safetyCentre.question1": "మీరు వారి వ్యక్తిగత UPI ఖాతాలో ప్రాసెసింగ్ రుసుమును చెల్లిస్తే, మీరు ఖచ్చితంగా ప్రభుత్వ స్కీమ్ ప్రయోజనాన్ని అందుకుంటారని ఒక వ్యక్తి క్లెయిమ్ చేస్తున్నారు. మీరు ఏమి చేయాలి?",
    "safetyCentre.question2": "మీ స్కీమ్ అప్లికేషన్‌ను ఆమోదించడానికి ఫోన్‌లో OTPని బహిర్గతం చేయమని ప్రభుత్వ అధికారి అని చెప్పుకునే ఎవరైనా మిమ్మల్ని అడుగుతారు. మీరు ఏమి చేయాలి?",
    "safetyCentre.question3": "మీరు గుర్తించని స్కీమ్ అప్లికేషన్ వెబ్‌సైట్‌కి లింక్‌తో కూడిన సందేశాన్ని అందుకుంటారు. మీరు ఏమి చేయాలి?",
    "safetyCentre.q2Option2": "వ్యక్తి నమ్మదగినదిగా అనిపిస్తే మాత్రమే షేర్ చేయండి.",
    "safetyCentre.q2Option3": "OTPని బహిర్గతం చేయవద్దు; స్వతంత్రంగా సంబంధిత అధికారిక సేవను సంప్రదించండి.",
    "safetyCentre.q2Option4": "బదులుగా మీ పాస్‌వర్డ్‌ను పంపండి.",
    "safetyCentre.q2Explanation": "కాలర్‌లకు OTPలు లేదా పాస్‌వర్డ్‌లను బహిర్గతం చేయవద్దు. మీరు స్వతంత్రంగా కనుగొనే సంప్రదింపు వివరాలను ఉపయోగించి అధికారిక సేవను సంప్రదించండి.",
    "safetyCentre.q3Option1": "వెంటనే మీ ఆధార్ మరియు బ్యాంక్ వివరాలను నమోదు చేయండి.",
    "safetyCentre.q3Option2": "ఇతర దరఖాస్తుదారులకు లింక్‌ను ఫార్వార్డ్ చేయండి.",
    "safetyCentre.q3Option3": "అధికారిక ప్రభుత్వ మూలం ద్వారా అప్లికేషన్ లింక్‌ను ధృవీకరించండి.",
    "safetyCentre.q3Option4": "వెబ్‌సైట్‌లో ప్రభుత్వ లోగో ఉన్నందున దానిని విశ్వసించండి.",
    "safetyCentre.q3Explanation": "వెబ్‌సైట్ నిజమైనదని లోగో నిరూపించదు. వివరాలను భాగస్వామ్యం చేయడానికి ముందు అధికారిక ప్రభుత్వ వెబ్‌సైట్ ద్వారా అప్లికేషన్ లింక్‌ను కనుగొనండి.",
    "safetyCentre.q4Option1": "ఆఫర్ ఆకర్షణీయంగా ఉన్నందున చెల్లించండి.",
    "safetyCentre.q4Option2": "క్లెయిమ్‌ను జాగ్రత్తగా పరిగణించండి మరియు అధికారిక మూలం ద్వారా పథకం యొక్క అర్హత నియమాలను ధృవీకరించండి.",
    "safetyCentre.q4Option3": "వ్యాఖ్యలలో వ్యక్తిగత పత్రాలను భాగస్వామ్యం చేయండి.",
    "safetyCentre.q4Option4": "పోస్ట్‌ను విశ్వసించండి ఎందుకంటే దీనికి చాలా ఇష్టాలు ఉన్నాయి.",
