    "safetyCentre.q4Explanation": "చట్టబద్ధమైన ప్రయోజనాలకు పథకం నియమాలు మరియు అర్హత ప్రమాణాలు ఉన్నాయి. గ్యారెంటీ ఎంపిక యొక్క ఇష్టాలు మరియు వాగ్దానాలు రుజువు కాదు.",
    "safetyCentre.q5Option1": "ప్రతిదీ వెంటనే పంపండి.",
    "safetyCentre.q5Option2": "మీ పాస్‌వర్డ్‌లను మాత్రమే షేర్ చేయండి.",
    "safetyCentre.q5Option3": "వ్యక్తి యొక్క అధికారాన్ని ధృవీకరించండి మరియు అధికారిక అప్లికేషన్ ఛానెల్‌ని ఉపయోగించండి; పాస్‌వర్డ్‌లు లేదా OTPలను ఎప్పుడూ బహిర్గతం చేయవద్దు.",
    "safetyCentre.q5Option4": "వారి గుర్తింపును నిర్ధారించడానికి వ్యక్తికి చెల్లించండి.",
    "safetyCentre.q5Explanation": "ధృవీకరించబడిన అప్లికేషన్ ఛానెల్‌ల ద్వారా మాత్రమే అవసరమైన పత్రాలను భాగస్వామ్యం చేయండి. పాస్‌వర్డ్‌లు, పిన్‌లు లేదా OTPలను మధ్యవర్తికి ఎప్పుడూ బహిర్గతం చేయవద్దు.",
    "safetyCentre.q6Option1": "వెంటనే డబ్బు బదిలీ చేయండి.",
    "safetyCentre.q6Option2": "మీ బ్యాంకింగ్ ఆధారాలతో ప్రత్యుత్తరం ఇవ్వండి.",
    "safetyCentre.q6Option3": "చర్య తీసుకునే ముందు సంబంధిత అధికారిక సేవ ద్వారా దావాను స్వతంత్రంగా ధృవీకరించండి.",
    "safetyCentre.q6Option4": "సందేశంలోని ప్రతి లింక్‌పై క్లిక్ చేయండి.",
    "safetyCentre.q6Explanation": "అత్యవసరం మరియు బెదిరింపులు సాధారణ ఒత్తిడి వ్యూహాలు. చర్య తీసుకునే ముందు పథకం యొక్క అధికారిక సేవను స్వతంత్రంగా సంప్రదించండి.",
