    "profile.occupation": "ಉದ್ಯೋಗ",
    "safetyCentre.step1Body": "ಸ್ಕೀಮ್ ಅಸ್ತಿತ್ವದಲ್ಲಿದೆಯೇ, ಯಾರು ಅರ್ಹರು, ಯಾವ ದಾಖಲೆಗಳು ಅಗತ್ಯವಿದೆ ಮತ್ತು ಸೂಕ್ತವಾದ ಅಧಿಕೃತ ಸರ್ಕಾರಿ ಮೂಲದ ಮೂಲಕ ಹೇಗೆ ಅರ್ಜಿ ಸಲ್ಲಿಸಬೇಕು ಎಂಬುದನ್ನು ಪರಿಶೀಲಿಸಿ.",
    "safetyCentre.step2Title": "ಅಪ್ಲಿಕೇಶನ್ ಲಿಂಕ್ ಅನ್ನು ಪರಿಶೀಲಿಸಿ",
    "safetyCentre.step2Body": "ವಿಶ್ವಾಸಾರ್ಹ ಸರ್ಕಾರಿ ಮೂಲದಿಂದ ಅಪ್ಲಿಕೇಶನ್ ಅನ್ನು ತಲುಪಿ. ಫಾರ್ವರ್ಡ್ ಮಾಡಿದ ಲಿಂಕ್‌ಗಳು, ಸಂಕ್ಷಿಪ್ತ URL ಗಳು ಅಥವಾ ಸರ್ಕಾರಿ ಲೋಗೋವನ್ನು ಮಾತ್ರ ಅವಲಂಬಿಸಬೇಡಿ.",
    "safetyCentre.step3Title": "ಪಾವತಿಗಳೊಂದಿಗೆ ಜಾಗರೂಕರಾಗಿರಿ",
    "safetyCentre.step3Body": "ಯಾವುದೇ ಶುಲ್ಕಕ್ಕಾಗಿ ಯೋಜನೆಯ ಅಧಿಕೃತ ಸೂಚನೆಗಳನ್ನು ಪರಿಶೀಲಿಸಿ. ಖಾತರಿಯ ಅನುಮೋದನೆಗೆ ಬದಲಾಗಿ ವೈಯಕ್ತಿಕ ಬ್ಯಾಂಕ್ ಅಥವಾ UPI ಪಾವತಿ ಬೇಡಿಕೆಗಳ ಬಗ್ಗೆ ಜಾಗರೂಕರಾಗಿರಿ.",
    "safetyCentre.step4Title": "ವೈಯಕ್ತಿಕ ಮಾಹಿತಿಯನ್ನು ರಕ್ಷಿಸಿ",
    "safetyCentre.step4Body": "ಪಾಸ್‌ವರ್ಡ್‌ಗಳು, ಪಿನ್‌ಗಳು ಅಥವಾ OTP ಗಳನ್ನು ಮಧ್ಯವರ್ತಿಯೊಂದಿಗೆ ಎಂದಿಗೂ ಹಂಚಿಕೊಳ್ಳಬೇಡಿ. ಪರಿಶೀಲಿಸಿದ ಅಪ್ಲಿಕೇಶನ್ ಚಾನಲ್ ಮೂಲಕ ಮಾತ್ರ ಅಗತ್ಯ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸಿ.",
    "safetyCentre.step5Title": "ಅನಿರೀಕ್ಷಿತ ಸಂದೇಶಗಳನ್ನು ಪರಿಶೀಲಿಸಿ",
    "safetyCentre.step5Body": "ಪ್ರತ್ಯುತ್ತರ ನೀಡುವ ಮೊದಲು, ಲಿಂಕ್‌ಗಳನ್ನು ತೆರೆಯುವ, ಹಣವನ್ನು ಕಳುಹಿಸುವ ಅಥವಾ ಮಾಹಿತಿಯನ್ನು ಹಂಚಿಕೊಳ್ಳುವ ಮೊದಲು ಅನುಮಾನಾಸ್ಪದ ಕರೆಗಳು, ಪಠ್ಯಗಳು, ಇಮೇಲ್‌ಗಳು ಮತ್ತು ಸಾಮಾಜಿಕ ಪೋಸ್ಟ್‌ಗಳನ್ನು ಸ್ವತಂತ್ರವಾಗಿ ಪರಿಶೀಲಿಸಿ.",
    "safetyCentre.resourcesTitle": "ತುರ್ತು ಸಹಾಯ ಮತ್ತು ಅಧಿಕೃತ ಸಂಪನ್ಮೂಲಗಳು",
