    "assistant.welcome": "ನಮಸ್ತೆ! ಪ್ರಸ್ತುತ ಸ್ಕೀಮ್ ಕ್ಯಾಟಲಾಗ್‌ನಿಂದ ಮಾಹಿತಿಯನ್ನು ಹುಡುಕಲು ನಾನು ನಿಮಗೆ ಸಹಾಯ ಮಾಡಬಹುದು. ನಾನು ವೈಯಕ್ತಿಕ ಅರ್ಹತೆಯನ್ನು ಖಚಿತಪಡಿಸಲು ಅಥವಾ ಅರ್ಜಿಗಳನ್ನು ಸಲ್ಲಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.",
