    "assistant.welcome": "നമസ്തേ! നിലവിലെ സ്കീം കാറ്റലോഗിൽ നിന്ന് വിവരങ്ങൾ കണ്ടെത്താൻ എനിക്ക് നിങ്ങളെ സഹായിക്കാനാകും. എനിക്ക് വ്യക്തിപരമായ യോഗ്യത സ്ഥിരീകരിക്കാനോ അപേക്ഷകൾ സമർപ്പിക്കാനോ കഴിയില്ല.",
