    "profile.occupation": "തൊഴിൽ",
    "safetyCentre.step1Body": "സ്കീം നിലവിലുണ്ടോ, ആരാണ് യോഗ്യൻ, ഏതൊക്കെ രേഖകൾ ആവശ്യമാണ്, ഉചിതമായ സർക്കാർ ഉറവിടം വഴി എങ്ങനെ അപേക്ഷിക്കാം എന്നിവ പരിശോധിക്കുക.",
    "safetyCentre.step2Title": "ആപ്ലിക്കേഷൻ ലിങ്ക് പരിശോധിക്കുക",
    "safetyCentre.step2Body": "ഒരു വിശ്വസനീയ സർക്കാർ ഉറവിടത്തിൽ നിന്ന് അപേക്ഷയിൽ എത്തിച്ചേരുക. ഫോർവേഡ് ലിങ്കുകൾ, ചുരുക്കിയ URL-കൾ, അല്ലെങ്കിൽ സർക്കാർ ലോഗോ എന്നിവയെ മാത്രം ആശ്രയിക്കരുത്.",
    "safetyCentre.step3Title": "പണമിടപാടുകൾ ശ്രദ്ധിക്കുക",
    "safetyCentre.step3Body": "ഏതെങ്കിലും ഫീസിനായി സ്കീമിൻ്റെ ഔദ്യോഗിക നിർദ്ദേശങ്ങൾ പരിശോധിക്കുക. ഗ്യാരണ്ടീഡ് അംഗീകാരത്തിന് പകരമായി വ്യക്തിഗത ബാങ്ക് അല്ലെങ്കിൽ യുപിഐ പേയ്‌മെൻ്റ് ആവശ്യങ്ങളിൽ ജാഗ്രത പാലിക്കുക.",
    "safetyCentre.step4Title": "വ്യക്തിഗത വിവരങ്ങൾ പരിരക്ഷിക്കുക",
    "safetyCentre.step4Body": "ഒരു ഇടനിലക്കാരനുമായി ഒരിക്കലും പാസ്‌വേഡുകളോ PIN-കളോ OTP-കളോ പങ്കിടരുത്. പരിശോധിച്ചുറപ്പിച്ച ആപ്ലിക്കേഷൻ ചാനലിലൂടെ മാത്രം ആവശ്യമായ രേഖകൾ സമർപ്പിക്കുക.",
    "safetyCentre.step5Title": "അപ്രതീക്ഷിത സന്ദേശങ്ങൾ പരിശോധിക്കുക",
    "safetyCentre.step5Body": "മറുപടി നൽകുന്നതിനും ലിങ്കുകൾ തുറക്കുന്നതിനും പണം അയയ്ക്കുന്നതിനും വിവരങ്ങൾ പങ്കിടുന്നതിനും മുമ്പ് സംശയാസ്പദമായ കോളുകൾ, ടെക്‌സ്റ്റുകൾ, ഇമെയിലുകൾ, സോഷ്യൽ പോസ്റ്റുകൾ എന്നിവ സ്വതന്ത്രമായി പരിശോധിക്കുക.",
    "safetyCentre.resourcesTitle": "അടിയന്തര സഹായവും ഔദ്യോഗിക ഉറവിടങ്ങളും",
    "safetyCentre.heroSubtitle": "വഞ്ചനാപരമായ സ്കീം ഓഫറുകൾ തിരിച്ചറിയാനും നിങ്ങളുടെ സ്വകാര്യ വിവരങ്ങൾ പരിരക്ഷിക്കാനും വിശ്വസനീയമായ ഉറവിടങ്ങൾ വഴി സുരക്ഷിതമായി അപേക്ഷിക്കാനും പഠിക്കുക.",
    "safetyCentre.takeQuiz": "സുരക്ഷാ ക്വിസ് എടുക്കുക",
    "safetyCentre.quizTitle": "അഴിമതി ബോധവൽക്കരണ ക്വിസ്",
    "safetyCentre.quizDescription": "ഓരോ സാഹചര്യത്തിലും ഏറ്റവും സുരക്ഷിതമായ പ്രതികരണം തിരഞ്ഞെടുക്കുക. നിങ്ങൾ പോകുമ്പോൾ പഠിക്കുക.",
