    "safetyCentre.incorrectFeedback": "അത് ഏറ്റവും സുരക്ഷിതമായ തിരഞ്ഞെടുപ്പല്ല.",
    "safetyCentre.correctAnswer": "ശരിയായ ഉത്തരം",
