    "safetyCentre.next": "അടുത്തത്",
    "safetyCentre.showResults": "നിങ്ങളുടെ സ്കോർ കാണുക",
    "safetyCentre.answerAll": "നിങ്ങളുടെ സ്കോർ കാണുന്നതിന് ആറ് ചോദ്യങ്ങൾക്കും ഉത്തരം നൽകുക.",
    "safetyCentre.quizComplete": "ക്വിസ് പൂർത്തിയായി",
