    "safetyCentre.q4Explanation": "നിയമാനുസൃതമായ ആനുകൂല്യങ്ങൾക്ക് സ്കീം നിയമങ്ങളും യോഗ്യതാ മാനദണ്ഡവുമുണ്ട്. ഉറപ്പുള്ള തിരഞ്ഞെടുപ്പിൻ്റെ ലൈക്കുകളും വാഗ്ദാനങ്ങളും തെളിവല്ല.",
