    "safetyCentre.q5Option2": "നിങ്ങളുടെ പാസ്‌വേഡുകൾ മാത്രം പങ്കിടുക.",
    "safetyCentre.q5Option3": "വ്യക്തിയുടെ അധികാരം പരിശോധിച്ച് ഔദ്യോഗിക ആപ്ലിക്കേഷൻ ചാനൽ ഉപയോഗിക്കുക; പാസ്‌വേഡുകളോ ഒടിപികളോ ഒരിക്കലും വെളിപ്പെടുത്തരുത്.",
    "safetyCentre.q5Option4": "വ്യക്തിയുടെ ഐഡൻ്റിറ്റി സ്ഥിരീകരിക്കാൻ പണം നൽകുക.",
    "safetyCentre.q5Explanation": "പരിശോധിച്ചുറപ്പിച്ച ആപ്ലിക്കേഷൻ ചാനലുകളിലൂടെ മാത്രം ആവശ്യമായ രേഖകൾ പങ്കിടുക. ഒരു ഇടനിലക്കാരന് ഒരിക്കലും പാസ്‌വേഡുകളോ പിന്നുകളോ OTP-കളോ വെളിപ്പെടുത്തരുത്.",
    "safetyCentre.q6Option1": "ഉടൻ പണം കൈമാറുക.",
    "safetyCentre.q6Option2": "നിങ്ങളുടെ ബാങ്കിംഗ് ക്രെഡൻഷ്യലുകൾ ഉപയോഗിച്ച് മറുപടി നൽകുക.",
    "safetyCentre.q6Option3": "നടപടിയെടുക്കുന്നതിന് മുമ്പ് പ്രസക്തമായ ഔദ്യോഗിക സേവനത്തിലൂടെ ക്ലെയിം സ്വതന്ത്രമായി പരിശോധിക്കുക.",
    "safetyCentre.q6Option4": "സന്ദേശത്തിലെ എല്ലാ ലിങ്കിലും ക്ലിക്ക് ചെയ്യുക.",
    "safetyCentre.q6Explanation": "അടിയന്തിരവും ഭീഷണിയും സാധാരണ സമ്മർദ്ദ തന്ത്രങ്ങളാണ്. പ്രവർത്തിക്കുന്നതിന് മുമ്പ് സ്കീമിൻ്റെ ഔദ്യോഗിക സേവനവുമായി സ്വതന്ത്രമായി ബന്ധപ്പെടുക.",
