    "dashboard.aiPrincipleDescription": "റൂൾ മൂല്യനിർണ്ണയങ്ങൾ ഔദ്യോഗിക സ്കീം ആട്രിബ്യൂട്ടുകളെ അടിസ്ഥാനമാക്കിയുള്ള നിർണ്ണായക കോഡാണ്. AI അസിസ്റ്റൻ്റ് ആ നിയമങ്ങളെ അടിസ്ഥാനമാക്കി വിശദീകരണങ്ങൾ ഫോർമാറ്റ് ചെയ്യുകയും റാങ്ക് ചെയ്യുകയും ചെയ്യുന്നു.",
